import React, { useEffect, useRef, useState } from 'react';
import { Badge, Button, EmptyState, Input, Logo, Modal, PoweredBy, Select, Tabs, Table, Textarea } from '@scaleinsyght/ui';
import { createRoot } from 'react-dom/client';
import './style.css';
import './phase1.css';
import './phase3.css';
import './phase5.css';
import './shell.css';

type Usage = { active_users: number; active_connectors: { by_type: Record<string, number> }; model_usage:{input_tokens:number;output_tokens:number;cost_usd:number;daily_cost_cap_usd:number;daily_token_cap:number} };
type NavGroups = { workspace: boolean; platform: boolean; recent: boolean };
type Connection = { connectionId: string; connectorType: string; displayName: string; status: string; agentId: string | null; lastJobState: string | null };
type GatewayInfo = { gatewayId: string; sourceConnectionId: string; lastSeenAt: string | null; revokedAt: string | null };
type Notification = { notificationId: string; type: string; summary: Record<string, unknown>; readAt: string | null };
function notificationCopy(item:Notification){
  if(item.type==='report_impact')return {title:'A connected report may be affected',detail:'Review the impact of a change to connected metadata.'};
  const profiled=Number(item.summary.profiled??0),listed=Number(item.summary.listed??0);
  if(item.type==='discovery')return {title:'Discovery completed',detail:`${profiled.toLocaleString()} objects profiled from ${listed.toLocaleString()} listed.`};
  if(item.type==='nightly')return {title:'Nightly profile completed',detail:profiled?`${profiled.toLocaleString()} objects profiled from ${listed.toLocaleString()} listed.`:'Overnight profiling and lineage checks are complete.'};
  return {title:'Your workspace was updated',detail:profiled?`${profiled.toLocaleString()} objects profiled and available for analysis.`:'A recent profile or review has new information.'};
}
type IdentifierField = { asset_id: string; field_name: string; entity_hint: string | null; format_pattern: string; detection: string; confidence: number; assertion_id: string | null };
type GraphView = { asset_ids: string[]; assets: Array<{ asset_id: string; qualified_name: string; asset_type: string; active: boolean }>; edges: Array<{ relationship_id: string; from_asset_id: string; to_asset_id: string; granularity: string }>; assertions: Array<{ assertion_id: string; relationship_id: string; evidence_method: string; review_status: string; verification: string; confidence_score: number | null; evidence_ids: string[]; explanation: string | null }>; gaps: Array<{ gap_id: string; reason: string }>; coverage: number; observable: boolean };
type GraphReport = { asset_id: string; name: string; tool: string | null; safe_path: string | null; lineage_assertions: number };
type GraphSnapshot = { snapshot_id: string; captured_at: string; event_cursor: number; asset_count: number };
type GraphAsset = { asset_id: string; qualified_name: string; asset_type: string; active: boolean };
type ErRelationship = { relationship_type: string; granularity: string; from_name: string; to_name: string; evidence_method: string | null; review_status: string | null; verification: string | null };

function uiCopy(value:string) {
  return value.replace(/\binsyght_reader\b/gi,'read-only connector').replace(/\bsi_(?:app|worker|migrate)\b/gi,'application role').replace(/\b[0-9a-f]{8}-[0-9a-f-]{27,}\b/gi,'').replaceAll('_',' ').replace(/\s{2,}/g,' ').trim();
}
function displayAssetName(value:string) { return uiCopy(value); }
function initials(name:string|undefined) { return name?.trim().split(/\s+/).filter(Boolean).slice(0,2).map(part=>part[0]?.toUpperCase()).join('')??''; }
function assetTypeLabel(value:string) { return ({dataset:'Table',field:'Column',report:'Report',metric:'Measure'} as Record<string,string>)[value]??'Connected object'; }
function adapterDisplayName(value:string) { return uiCopy(value); }
function connectorTypeLabel(type:string) {
  const kind=type.toLowerCase();
  if(kind.includes('postgres')||kind.includes('sql_server')||kind.includes('snowflake')||kind==='mssql')return 'Database connection';
  if(kind.includes('excel'))return 'Workbook connection';
  if(kind==='dbt')return 'Data model';
  if(kind.includes('tableau')||kind.includes('power_bi'))return 'Report catalog';
  return 'Connected source';
}
function connectionDisplayName(connection:Connection) { return connection.displayName || 'Connected source'; }

function LineageWorkspace(props: { path: string; navigate: (path: string) => void }) {
  const [fields,setFields]=useState<IdentifierField[]>([]); const [lineage,setLineage]=useState<GraphView|null>(null);
  const [assets,setAssets]=useState<GraphAsset[]>([]);const [idPath,setIdPath]=useState<Array<{assetId:string;fieldName:string}>>([]);
  const [reports,setReports]=useState<GraphReport[]>([]); const [snapshots,setSnapshots]=useState<GraphSnapshot[]>([]);
  const [selected,setSelected]=useState(''); const [direction,setDirection]=useState<'both'|'upstream'|'downstream'>('both');
  const [value,setValue]=useState(''); const [matches,setMatches]=useState<Array<{asset_id:string;field_name:string;entity_hint:string|null;format_pattern:string}>>([]);
  const [fromSnapshot,setFromSnapshot]=useState(''); const [toSnapshot,setToSnapshot]=useState(''); const [changes,setChanges]=useState<Array<{event_type:string;asset_id:string|null}>>([]);
  const [message,setMessage]=useState(''); const [error,setError]=useState('');
  const [erRelationships,setErRelationships]=useState<ErRelationship[]>([]);
  const selectedRef=useRef('');const lineageRequestRef=useRef(0);
  const view=props.path.startsWith('/bi-reports')?'reports':props.path.startsWith('/er')?'er':props.path.includes('/columns')?'columns':props.path.includes('/ids')?'ids':props.path.includes('/compare')?'compare':props.path.includes('/impact/')?'impact':'lineage';
  async function reload(){
    const requestId=++lineageRequestRef.current;
    const [identifierData,reportData,snapshotData,assetData]=await Promise.all([
      api<{fields:IdentifierField[]}>('/api/ids'),api<{reports:GraphReport[]}>('/api/reports'),api<{snapshots:GraphSnapshot[]}>('/api/lineage/snapshots'),api<{assets:GraphAsset[]}>('/api/lineage/assets'),
    ]);
    setFields(identifierData.fields);setReports(reportData.reports);setSnapshots(snapshotData.snapshots);setAssets(assetData.assets);
    const currentSelection=selectedRef.current||selected;
    const defaultAsset=assetData.assets.find(asset=>asset.asset_type==='dataset')?.asset_id??assetData.assets[0]?.asset_id??identifierData.fields[0]?.asset_id??'';
    const active=(currentSelection&&assetData.assets.some(asset=>asset.asset_id===currentSelection))?currentSelection:defaultAsset;
    if(active){selectedRef.current=active;setSelected(active);}
    if(active&&requestId===lineageRequestRef.current){const data=await api<GraphView>(`/api/lineage?assetId=${encodeURIComponent(active)}&direction=${direction}`);if(requestId===lineageRequestRef.current)setLineage(data);}
    if(identifierData.fields.some(field=>field.asset_id===active)){const path=await api<{fields:Array<{assetId:string;fieldName:string}>}>(`/api/ids/${active}/path`);if(requestId===lineageRequestRef.current)setIdPath(path.fields);}
    if(!fromSnapshot&&snapshotData.snapshots[0])setFromSnapshot(snapshotData.snapshots[0].snapshot_id);
    if(!toSnapshot&&snapshotData.snapshots.at(-1))setToSnapshot(snapshotData.snapshots.at(-1)!.snapshot_id);
  }
  useEffect(()=>{void reload().catch(reason=>setError(reason instanceof Error?reason.message:'Lineage could not be loaded.'));},[]);
  useEffect(()=>{if(view!=='er')return;const connectionId=new URLSearchParams(location.search).get('connection');if(!connectionId)return;void api<{relationships:ErRelationship[]}>(`/api/connections/${encodeURIComponent(connectionId)}/er`).then(result=>setErRelationships(result.relationships)).catch(reason=>setError(reason instanceof Error?reason.message:'Entity relationships could not be loaded.'));},[view,location.search]);
  async function chooseAsset(assetId:string){selectedRef.current=assetId;setSelected(assetId);const requestId=++lineageRequestRef.current;try{const data=await api<GraphView>(`/api/lineage?assetId=${encodeURIComponent(assetId)}&direction=${direction}`);if(requestId===lineageRequestRef.current)setLineage(data);if(fields.some(field=>field.asset_id===assetId)){const path=await api<{fields:Array<{assetId:string;fieldName:string}>}>(`/api/ids/${assetId}/path`);if(requestId===lineageRequestRef.current)setIdPath(path.fields);}}catch(reason){setError(reason instanceof Error?reason.message:'Lineage could not be loaded.');}}
  async function trace(event:React.FormEvent){event.preventDefault();setError('');try{const result=await api<{matches:typeof matches}>(`/api/ids/${selected}/trace`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({value})});setMatches(result.matches);setMessage(result.matches.length?'Identifier match found.':'No matching fingerprint was found.');}catch(reason){setError(reason instanceof Error?reason.message:'Identifier trace failed.');}finally{setValue('');}}
  async function compare(){if(!fromSnapshot||!toSnapshot)return;try{const result=await api<{changes:typeof changes}>(`/api/lineage/snapshots/${fromSnapshot}/compare/${toSnapshot}`);setChanges(result.changes);}catch(reason){setError(reason instanceof Error?reason.message:'Snapshots could not be compared.');}}
  async function review(assertionId:string){try{await api(`/api/lineage/assertions/${assertionId}/review`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({status:'accepted'})});setMessage('Assertion accepted; its verification status is unchanged.');await reload();}catch(reason){setError(reason instanceof Error?reason.message:'Assertion review failed.');}}
  const label=(assetId:string)=>displayAssetName(lineage?.assets.find(asset=>asset.asset_id===assetId)?.qualified_name??'Connected data');
  const erTables=[...erRelationships.reduce((grouped,item)=>{if(item.relationship_type==='CONTAINS'){const columns=grouped.get(item.from_name)??[];columns.push(item.to_name);grouped.set(item.from_name,columns);}return grouped;},new Map<string,string[]>()).entries()];
  const erNodes=erTables.map(([table,columns],index)=>({table,columns,x:24+(index%3)*320,y:24+Math.floor(index/3)*260}));
  const erTableFor=(name:string)=>erNodes.map(node=>node.table).sort((a,b)=>b.length-a.length).find(table=>name===table||name.startsWith(`${table}.`));
  const erLinks=[...new Map(erRelationships.filter(item=>item.relationship_type!=='CONTAINS').map(item=>{const from=erTableFor(item.from_name),to=erTableFor(item.to_name);return from&&to&&from!==to?[[from,to,item.relationship_type].join('|'),{from,to,type:item.relationship_type,evidence:item.evidence_method??'declared'}] as const:null;}).filter((item):item is readonly [string,{from:string;to:string;type:string;evidence:string}]=>Boolean(item)))].map(([,link])=>link);
  const erWidth=erNodes.length?Math.max(980,Math.ceil(erNodes.length/3)*320):980;
  const erHeight=Math.max(320,Math.ceil(erNodes.length/3)*260+40);
  return <section className="phase3-workspace"><div className="page-heading"><div><p className="eyebrow">{view==='er'?'Relationships':'Data connections'}</p><h1>{view==='ids'?'ID trace':view==='impact'?'Impact analysis':view==='compare'?'Snapshot compare':view==='reports'?'BI reports':view==='er'?'ER explorer':view==='columns'?'Column lineage':'Lineage workspace'}</h1></div></div>
    <nav className="phase3-tabs" aria-label="Lineage workspace views"><a href="/lineage" aria-current={view==='lineage'?'page':undefined} onClick={event=>{event.preventDefault();props.navigate('/lineage');}}>Lineage</a><a href="/lineage/columns" aria-current={view==='columns'?'page':undefined} onClick={event=>{event.preventDefault();props.navigate('/lineage/columns');}}>Columns</a><a href="/er" aria-current={view==='er'?'page':undefined} onClick={event=>{event.preventDefault();props.navigate('/er');}}>ER explorer</a><a href="/lineage/ids" aria-current={view==='ids'?'page':undefined} onClick={event=>{event.preventDefault();props.navigate('/lineage/ids');}}>ID trace</a><a href="/lineage/impact" aria-current={view==='impact'?'page':undefined} onClick={event=>{event.preventDefault();props.navigate('/lineage/impact');}}>Impact</a><a href="/lineage/compare" aria-current={view==='compare'?'page':undefined} onClick={event=>{event.preventDefault();props.navigate('/lineage/compare');}}>Snapshot compare</a><a href="/bi-reports" aria-current={view==='reports'?'page':undefined} onClick={event=>{event.preventDefault();props.navigate('/bi-reports');}}>BI reports</a></nav>
    {view==='ids'&&<article className="id-lookup"><h2>Look up one value</h2><p>Answered live and read-only for people entitled to see it. The value goes directly to the queries, never to the AI model.</p><form onSubmit={event=>void trace(event)}><label>Value to trace<Input aria-label="Value to trace" autoComplete="off" maxLength={256} value={value} onChange={event=>setValue(event.target.value)} /></label><Button variant="primary" type="submit" disabled={!selected||!value}>Trace</Button></form></article>}
    {view!=='er'&&<div className="phase3-toolbar"><label>{view==='ids'?'Identifier field':'Graph asset'}<Select aria-label={view==='ids'?'Identifier field':'Graph asset'} value={selected} onChange={event=>void chooseAsset(event.target.value)}><option value="">Choose {view==='ids'?'a detected field':'an asset'}</option>{(view==='ids'?fields.map(field=>({asset_id:field.asset_id,label:`${field.entity_hint??'Identifier'} · ${field.field_name} · ${field.format_pattern}`})):assets.map(asset=>({asset_id:asset.asset_id,label:`${displayAssetName(asset.qualified_name)} · ${assetTypeLabel(asset.asset_type)}`}))).map(item=><option key={`${item.asset_id}-${item.label}`} value={item.asset_id}>{item.label}</option>)}</Select></label>{view==='lineage'&&<label>Direction<Select aria-label="Lineage direction" value={direction} onChange={event=>{const next=event.target.value as typeof direction;setDirection(next);if(selected){const requestId=++lineageRequestRef.current;void api<GraphView>(`/api/lineage?assetId=${encodeURIComponent(selected)}&direction=${next}`).then(data=>{if(requestId===lineageRequestRef.current)setLineage(data);});}}}><option value="both">Both directions</option><option value="upstream">Upstream</option><option value="downstream">Downstream</option></Select></label>}</div>}
    {error&&<p className="error" role="alert">{error}</p>}{message&&<p role="status">{message}</p>}
    {(view==='lineage'||view==='columns')&&<div className="lineage-layout"><article><h2>Data flow</h2>{!lineage||lineage.edges.length===0?<EmptyState title="No lineage to show yet" description="Connect a source to explore how data moves between tables and reports." action={<Button onClick={()=>props.navigate('/connectors')}>Open Connectors</Button>} />:<><p>{Math.round(lineage.coverage*100)}% observed coverage · {lineage.gaps.length} documented gaps</p>{view==='columns'?<Table caption="Column level data flow" headers={['Source column','Destination column','Evidence']} rows={lineage.edges.map(edge=>[<span key="source">{label(edge.from_asset_id)}</span>,<span key="destination">{label(edge.to_asset_id)}</span>,<Badge key="evidence" tone="good">Observed</Badge>])}/>:<ol className="lineage-edges">{lineage.edges.map(edge=><li key={edge.relationship_id}><span>{label(edge.from_asset_id)}</span><b aria-hidden="true">→</b><span>{label(edge.to_asset_id)}</span><small>{edge.granularity} · evidence-backed</small></li>)}</ol>}{lineage.gaps.map(gap=><p className="graph-gap" key={gap.gap_id}>Missing hop · {uiCopy(gap.reason)}</p>)}</>}</article><article><h2>Assertions and evidence</h2>{lineage?.assertions.map(assertion=><div className="assertion-row" key={assertion.assertion_id}><p>{uiCopy(assertion.evidence_method)} · {uiCopy(assertion.review_status)}</p><p>Verification: {uiCopy(assertion.verification)}</p><p>{assertion.evidence_ids.length} evidence item(s)</p>{assertion.review_status==='unreviewed'&&<Button onClick={()=>void review(assertion.assertion_id)}>Accept assertion</Button>}</div>)}</article></div>}
    {view==='er'&&<article className="er-explorer"><div className="page-heading"><div><h2>Entity relationships</h2><p>Tables, their fields, and declared or probable relationships from this source.</p></div><strong>{erRelationships.length} relationships</strong></div>{erTables.length?<><div className="er-canvas-scroll"><div className="er-canvas" style={{width:erWidth,height:erHeight}}><svg className="er-links" viewBox={`0 0 ${erWidth} ${erHeight}`} role="img" aria-label="Entity relationship links"><defs><marker id="er-arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 z" /></marker></defs>{erLinks.map(link=>{const from=erNodes.find(node=>node.table===link.from)!,to=erNodes.find(node=>node.table===link.to)!;const x1=from.x+260,y1=from.y+84,x2=to.x,y2=to.y+84;const method=link.evidence.toLowerCase();const kind=method.includes('infer')?'inferred':method.includes('observ')?'observed':'declared';return <g key={`${link.from}-${link.to}-${link.type}`} className={`er-link er-link--${kind}`}><path d={`M${x1},${y1} C${x1+32},${y1} ${x2-32},${y2} ${x2},${y2}`} markerEnd="url(#er-arrow)"/><title>{displayAssetName(link.from)} to {displayAssetName(link.to)} · {uiCopy(link.type)} · {uiCopy(link.evidence)}</title></g>;})}</svg>{erNodes.map(node=><article className="er-node" key={node.table} style={{left:node.x,top:node.y}}><h3>{displayAssetName(node.table)}</h3><ul>{node.columns.slice(0,6).map(column=><li key={column}><span>{displayAssetName(column.split('.').at(-1)??column)}</span><small>Field</small></li>)}</ul>{node.columns.length>6&&<small className="er-more">+{node.columns.length-6} more fields</small>}<Button variant="ghost" size="small" onClick={()=>props.navigate(`/dictionary?connection=${new URLSearchParams(location.search).get('connection')??''}`)}>View table profile</Button></article>)}</div></div><div className="er-legend"><span><i className="er-legend-declared"/>Declared</span><span><i className="er-legend-inferred"/>Probable</span><span><i className="er-legend-observed"/>Observed</span></div></>:<EmptyState title="No entity relationships yet" description="Profile a connected source to discover declared and probable table relationships." action={<Button onClick={()=>props.navigate('/connectors')}>View connectors</Button>}/>}</article>}
    {view==='ids'&&<article><h2>Identifier path</h2>{fields.length===0?<p>No identifier fields detected yet.</p>:<><p>Only field metadata and tenant-keyed fingerprints are stored. Lookup values are discarded after each request.</p>{matches.length>0?<ul>{matches.map(match=><li key={`${match.asset_id}-${match.field_name}`}>{match.entity_hint} · {match.field_name} · {match.format_pattern}</li>)}</ul>:null}<ol>{idPath.map(field=><li key={`${field.assetId}-${field.fieldName}`}>{field.fieldName} · probable identifier path</li>)}</ol></>}</article>}
    {view==='impact'&&<article><h2>Downstream impact</h2>{lineage?.gaps.map(gap=><p className="graph-gap" key={gap.gap_id}>Incomplete path · {gap.reason}</p>)}{reports.map(report=><p key={report.asset_id}>{report.name} · {report.tool??'BI'} · {report.lineage_assertions} linked flow(s)</p>)}</article>}
    {view==='compare'&&<article><h2>Graph changes</h2><div className="snapshot-selects"><label>Earlier snapshot<Select aria-label="Earlier snapshot" value={fromSnapshot} onChange={event=>setFromSnapshot(event.target.value)}>{snapshots.map((snapshot,index)=><option key={snapshot.snapshot_id} value={snapshot.snapshot_id}>Snapshot {index+1} · {new Date(snapshot.captured_at).toLocaleString()} · {snapshot.asset_count} assets</option>)}</Select></label><label>Later snapshot<Select aria-label="Later snapshot" value={toSnapshot} onChange={event=>setToSnapshot(event.target.value)}>{snapshots.map((snapshot,index)=><option key={snapshot.snapshot_id} value={snapshot.snapshot_id}>Snapshot {index+1} · {new Date(snapshot.captured_at).toLocaleString()} · {snapshot.asset_count} assets</option>)}</Select></label><Button onClick={()=>void compare()}>Compare snapshots</Button></div><ul>{changes.map((change,index)=><li key={`${change.event_type}-${index}`}>{change.event_type.replaceAll('_',' ').toLowerCase()} · {change.asset_id?'A connected object changed':'Workspace structure changed'}</li>)}</ul>{snapshots.length===0&&<EmptyState title="No snapshots yet" description="Snapshots appear after your connected data has been profiled."/>}</article>}
    {view==='reports'&&<article><h2>Reports and lineage status</h2>{reports.map(report=><div className="report-row" key={report.asset_id}><div><strong>{displayAssetName(report.name)}</strong><p>{uiCopy(report.tool??'BI report')} · {report.lineage_assertions} linked flow(s)</p></div>{report.safe_path&&<a href={report.safe_path} aria-label={`Open ${displayAssetName(report.name)}`}>Open report</a>}</div>)}{reports.length===0&&<EmptyState title="No reports connected" description="Connect your reporting catalog to trace reports back to their source data." action={<Button onClick={()=>props.navigate('/connectors')}>Open Connectors</Button>} />}</article>}
  </section>;
}

async function api<T>(url: string, init?: RequestInit): Promise<T> {
  const response = await fetch(url, init);
  if (response.status === 401) throw new Error('unauthorized');
  if (!response.ok) {
    const result = await response.json().catch(() => ({})) as { error?: string };
    throw new Error(uiCopy((result.error ?? 'The request could not be completed.').replaceAll('_',' ')));
  }
  if (response.status === 204) return undefined as T;
  return response.json() as Promise<T>;
}

function Login() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const tenantId = new URLSearchParams(location.search).get('tenant') ?? '';
  const [organization,setOrganization]=useState('');
  const [ssoOpen,setSsoOpen]=useState(false);
  const [error, setError] = useState('');
  async function submit(event: React.FormEvent) {
    event.preventDefault(); setError('');
    try {
      await api('/api/auth/login', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ tenantId, email, password }) });
      if(tenantId)try{localStorage.setItem('si-login-tenant',tenantId);}catch{ /* Login remains successful when browser storage is disabled. */ }
      location.assign('/');
    } catch { setError('Email or password is incorrect.'); }
  }
  return <main className="login"><form onSubmit={submit}><div className="login-brand"><Logo /><span>insyght</span></div><p className="login-product">Scale Data Hub</p><h1>Sign in</h1><p>Connect your data, and your agents do the rest.</p><label>Work email<Input aria-label="Email" autoComplete="username" type="email" required value={email} onChange={event => setEmail(event.target.value)} /></label><label>Password<Input autoComplete="current-password" type="password" required value={password} onChange={event => setPassword(event.target.value)} /></label>{error && <p role="alert" className="error">{error}</p>}<Button variant="primary" type="submit">Sign in</Button><div className="login-divider">or</div><Button type="button" onClick={()=>setSsoOpen(true)}>Continue with single sign-on</Button><p className="muted">Your organization may use single sign-on.</p></form><PoweredBy />{ssoOpen&&<Modal title="Continue with single sign-on" open onClose={()=>setSsoOpen(false)}><p>Enter the organization workspace code provided by your administrator.</p><label>Organization workspace<Input aria-label="Organization workspace" value={organization} onChange={event=>setOrganization(event.target.value)} /></label><Button variant="primary" disabled={!organization.trim()} onClick={()=>location.assign(`/api/auth/oidc/${encodeURIComponent(organization)}/start`)}>Continue</Button></Modal>}</main>;
}


function InvitesPage(){
  const [email,setEmail]=useState('');const [inviteUrl,setInviteUrl]=useState('');const [expiresAt,setExpiresAt]=useState('');const [message,setMessage]=useState('');
  async function create(event:React.FormEvent){event.preventDefault();setMessage('');try{const result=await api<{inviteUrl:string;expiresAt:string}>('/api/tenant/invites',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({email})});setInviteUrl(result.inviteUrl);setExpiresAt(result.expiresAt);}catch(reason){setMessage(reason instanceof Error?reason.message:'Invite could not be created.');}}
  return <section className="page-section"><div className="page-heading"><div><h1>Invite members</h1><p>Create a single-use link that expires after 24 hours. Send it to the invited person.</p></div></div><form onSubmit={event=>void create(event)}><label>Email<Input aria-label="Email" type="email" required value={email} onChange={event=>setEmail(event.target.value)}/></label><Button variant="primary" type="submit">Create invite link</Button></form>{inviteUrl&&<div><label>Copyable invite link<Input aria-label="Copyable invite link" type="password" autoComplete="off" readOnly value={inviteUrl} onFocus={event=>event.currentTarget.select()}/></label><p>Expires {new Date(expiresAt).toLocaleString()}</p><Button onClick={()=>void navigator.clipboard.writeText(inviteUrl)}>Copy invite link</Button></div>}{message&&<p role="alert">{uiCopy(message)}</p>}</section>;
}

function InviteAcceptPage(){
  const query=new URLSearchParams(location.search);const tenantId=query.get('tenant')??'';const token=query.get('token')??'';
  const [displayName,setDisplayName]=useState('');const [password,setPassword]=useState('');const [accepted,setAccepted]=useState(false);const [error,setError]=useState('');
  async function accept(event:React.FormEvent){event.preventDefault();setError('');try{await api('/api/auth/invites/accept',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({tenantId,token,displayName,password})});setAccepted(true);}catch(reason){setError(reason instanceof Error?reason.message:'Invitation could not be accepted.');}}
  if(accepted)return <main className="login"><section><h1>Workspace access ready</h1><p>Your account is ready. Sign in to continue.</p><Button variant="primary" onClick={()=>location.assign(`/login?tenant=${encodeURIComponent(tenantId)}`)}>Go to sign in</Button></section><PoweredBy/></main>;
  return <main className="login"><form onSubmit={event=>void accept(event)}><div className="login-brand"><Logo/><span>insyght</span></div><p className="login-product">Scale Data Hub</p><h1>Accept invitation</h1><p>Set your name and password to join this workspace.</p><label>Your name<Input aria-label="Your name" required maxLength={120} value={displayName} onChange={event=>setDisplayName(event.target.value)}/></label><label>Create a password<Input aria-label="Create a password" type="password" minLength={12} required value={password} onChange={event=>setPassword(event.target.value)}/></label>{error&&<p role="alert" className="error">{uiCopy(error)}</p>}<Button variant="primary" type="submit" disabled={!tenantId||!token}>Accept invitation</Button></form><PoweredBy/></main>;
}

function loadGroups(): NavGroups {
  try { return { workspace: localStorage.getItem('nav-workspace') !== 'false', platform: localStorage.getItem('nav-platform') !== 'false', recent: localStorage.getItem('nav-recent') !== 'false' }; }
  catch { return { workspace: true, platform: true, recent: true }; }
}

function ConnectorsPage(props: { connections: Connection[]; reload: () => Promise<void>; navigate: (path: string) => void }) {
  const [connectionId,setConnectionId]=useState('');
  const [stage,setStage]=useState<'closed'|'form'|'scope'|'complete'>('closed');
  const [message,setMessage]=useState('');const [error,setError]=useState('');
  const [gatewayToken,setGatewayToken]=useState('');const [gatewayStatus,setGatewayStatus]=useState('');const [gatewaySourceId,setGatewaySourceId]=useState('');
  const [gateways,setGateways]=useState<GatewayInfo[]>([]);
  const [credential,setCredential]=useState({displayName:'',host:'',port:'5432',database:'',username:'',password:'',sslMode:'require'});
  const visibleConnections=props.connections.filter(connection=>connection.status==='active').sort((a,b)=>Number(Boolean(b.lastJobState))-Number(Boolean(a.lastJobState)));
  useEffect(()=>{void api<{gateways:GatewayInfo[]}>('/api/gateways').then(result=>setGateways(result.gateways)).catch(()=>setGatewayStatus('Gateway controls are not available for this account.'));},[]);
  async function issueGatewayToken(sourceConnectionId:string){setGatewayToken('');setGatewayStatus('');try{const result=await api<{token:string}>('/api/gateways/enrollments',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({sourceConnectionId})});setGatewayToken(result.token);setGatewayStatus('Enrollment token created. Copy it now; it is shown only once.');}catch(reason){setGatewayStatus(reason instanceof Error?reason.message:'Gateway enrollment failed.');}}
  async function revokeGateway(gatewayId:string){try{await api(`/api/gateways/${gatewayId}/revoke`,{method:'POST'});setGateways(await api<{gateways:GatewayInfo[]}>('/api/gateways').then(result=>result.gateways));setGatewayStatus('Gateway revoked.');}catch(reason){setGatewayStatus(reason instanceof Error?reason.message:'Gateway revocation failed.');}}
  async function createDraft(event:React.FormEvent){event.preventDefault();setError('');setMessage('');try{const created=await api<{connectionId:string}>('/api/connections',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({connectorType:'postgres',displayName:credential.displayName,credential:{...credential,port:Number(credential.port)}})});setConnectionId(created.connectionId);const tested=await api<{ok:boolean;readOnly:boolean}>(`/api/connections/${created.connectionId}/test`,{method:'POST'});if(!tested.ok||!tested.readOnly)throw new Error('The supplied login must be read-only.');setStage('scope');}catch(reason){setError(reason instanceof Error?reason.message:'Connection test failed. Check the host and read-only credentials.');}}
  async function activate(){setError('');try{const result=await api<{profile:{profiled:number;listed:number;inaccessible:number}}>(`/api/connections/${connectionId}/activate`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({scope:[]})});setMessage(`Connector agent created. Profile complete: ${result.profile.profiled} objects profiled from ${result.profile.listed} listed; ${result.profile.inaccessible} inaccessible.`);setStage('complete');await props.reload();}catch(reason){setError(reason instanceof Error?reason.message:'Activation failed. Confirm the database login has read-only access.');}}
  function close(){setStage('closed');setConnectionId('');setError('');}
  return <section className="connectors-page"><div className="page-heading"><div><p className="eyebrow">Data sources</p><h1>Connectors</h1><p>Connect sources and manage the profiles that keep your answers current.</p></div><Button variant="primary" onClick={()=>{setStage('form');setError('');setMessage('');}}>＋ Add connector</Button></div>
    {visibleConnections.length===0?<EmptyState title="No sources connected" description="Connect a read-only source to start building your catalog and profile." action={<Button variant="primary" onClick={()=>setStage('form')}>Add connector</Button>}/>:<div className="cards connector-grid">{visibleConnections.map(connection=><article className="connector-card" key={connection.connectionId}><div className="connector-card-head"><span className="connector-icon" aria-hidden="true">{connectionDisplayName(connection).split(' ').map(word=>word[0]).join('').slice(0,2)}</span><div><h2>{connectionDisplayName(connection)}</h2><small>{connectorTypeLabel(connection.connectorType)}</small></div><Badge tone="good">Connected</Badge></div><div className="connector-card-status"><Badge tone={connection.agentId?'good':'muted'}>{connection.agentId?'Agent created':'Connection active'}</Badge><Badge tone={connection.lastJobState?'primary':'warn'}>{connection.lastJobState?'Profiled':'Profile needed'}</Badge></div><p>Last profile: {connection.lastJobState?'Completed':'Not started'}</p><div className="actions"><Button size="small" onClick={()=>props.navigate(`/profile/${connection.connectionId}`)}>Profile</Button><Button size="small" onClick={()=>props.navigate(`/dictionary?connection=${connection.connectionId}`)}>Dictionary</Button><Button size="small" onClick={()=>props.navigate(`/er?connection=${connection.connectionId}`)}>ER diagram</Button></div></article>)}</div>}
    <article aria-label="Customer gateway administration"><h2>Private network gateways</h2><p>Connect sources that can only be reached from your organization’s network.</p><label>Private source<Select aria-label="Gateway source" value={gatewaySourceId} onChange={event=>setGatewaySourceId(event.target.value)}><option value="">Choose a source</option>{visibleConnections.map(connection=><option key={connection.connectionId} value={connection.connectionId}>{connectionDisplayName(connection)}</option>)}</Select></label><Button disabled={!gatewaySourceId} onClick={()=>void issueGatewayToken(gatewaySourceId)}>Create enrollment code</Button>{gateways.map(gateway=><p key={gateway.gatewayId}>Gateway · {gateway.revokedAt?'Disconnected':gateway.lastSeenAt?'Online':'Waiting for first connection'} {!gateway.revokedAt&&<Button onClick={()=>void revokeGateway(gateway.gatewayId)}>Disconnect</Button>}</p>)}{gatewayToken&&<label>One-time enrollment code<output aria-label="One-time enrollment code">{gatewayToken}</output></label>}{gatewayStatus&&<p role="status">{gatewayStatus}</p>}</article>
    {stage==='form'&&<Modal title="Add a PostgreSQL source" open onClose={close}><form onSubmit={event=>void createDraft(event)}><label>Connection name<Input aria-label="Connection name" required maxLength={120} value={credential.displayName} onChange={event=>setCredential({...credential,displayName:event.target.value})}/></label><label>Host<Input aria-label="Host" required value={credential.host} onChange={event=>setCredential({...credential,host:event.target.value})}/></label><label>Port<Input aria-label="Port" type="number" required value={credential.port} onChange={event=>setCredential({...credential,port:event.target.value})}/></label><label>Database<Input aria-label="Database" required value={credential.database} onChange={event=>setCredential({...credential,database:event.target.value})}/></label><label>Username<Input aria-label="Username" required value={credential.username} onChange={event=>setCredential({...credential,username:event.target.value})}/></label><label>Password<Input aria-label="Password" type="password" required value={credential.password} onChange={event=>setCredential({...credential,password:event.target.value})}/></label><label>SSL mode<Select aria-label="SSL mode" value={credential.sslMode} onChange={event=>setCredential({...credential,sslMode:event.target.value})}><option value="require">Require</option><option value="verify-full">Verify full</option><option value="disable">Disable</option></Select></label><p>Use credentials that can read the selected database but cannot create, update, or delete records.</p>{error&&<p role="alert" className="error">{uiCopy(error)}</p>}<div className="actions"><Button type="button" onClick={close}>Cancel</Button><Button variant="primary" type="submit">Test connection</Button></div></form></Modal>}
    {stage==='scope'&&<Modal title="Choose scope" open onClose={close}><p>Profile selected objects. Out-of-scope objects are never sampled or queried.</p><label className="checkbox-label"><Input type="checkbox" defaultChecked/>Profile objects from this source</label>{error&&<p role="alert" className="error">{uiCopy(error)}</p>}<div className="actions"><Button onClick={close}>Cancel</Button><Button variant="primary" onClick={()=>void activate()}>Start profiling</Button></div></Modal>}
    {stage==='complete'&&<Modal title="Discovery complete" open onClose={close}><p role="status">{message}</p><div className="actions"><Button onClick={close}>Close</Button></div></Modal>}
  </section>;
}
function ProfilePage(props: { connectionId: string; navigate: (path: string) => void }) {
  const [profile, setProfile] = useState<Record<string, unknown> | null>(null);
  const [classifications,setClassifications]=useState<Array<{qualified_name:string;sensitivity_tags:string[]}>>([]);
  const [loading,setLoading]=useState(true);
  useEffect(() => { let cancelled=false;let timer:ReturnType<typeof setTimeout>|undefined;let attempt=0;const load=()=>{void api<{profile:Record<string,unknown>|null;classifications:Array<{qualified_name:string;sensitivity_tags:string[]}>}>(`/api/connections/${props.connectionId}/profile`).then(result=>{if(cancelled)return;setClassifications(result.classifications);if(result.profile){setProfile(result.profile);setLoading(false);}else if(attempt++<20){timer=setTimeout(load,500);}else setLoading(false);}).catch(()=>{if(!cancelled)setLoading(false);});};load();return()=>{cancelled=true;if(timer)clearTimeout(timer);}; }, [props.connectionId]);
  const listed=Number(profile?.listed_count??0),profiled=Number(profile?.dataset_count??0),percent=listed?Math.round(profiled/listed*100):0;
  return <section className="profile-page"><div className="page-heading"><div><p className="eyebrow">Connector profile</p><h1>Profile</h1><p>See what was discovered, profiled, and made available for analysis.</p></div></div>{profile ? <><article className="profile-overview"><div className="profile-ring" role="img" aria-label={`${percent}% of listed objects profiled`} style={{'--ring-progress':`${percent}%`} as React.CSSProperties}><div><strong>{percent}%</strong><span>profiled</span></div></div><div className="profile-stats"><div><span>Objects listed</span><strong>{listed.toLocaleString()}</strong></div><div><span>Objects profiled</span><strong>{profiled.toLocaleString()}</strong></div><div><span>Fields profiled</span><strong>{Number(profile.field_count??0).toLocaleString()}</strong></div><div><span>Not accessible</span><strong>{Number(profile.inaccessible_count??0).toLocaleString()}</strong></div></div></article><div className="profile-categories"><article><span className="category-dot good"/><div><b>Ready for analysis</b><p>Objects are profiled and available to answers.</p></div><strong>{profiled.toLocaleString()}</strong></article><article><span className="category-dot warn"/><div><b>Listed only</b><p>Names and types are available; values are not read.</p></div><strong>{Math.max(0,listed-profiled).toLocaleString()}</strong></article><article><span className="category-dot bad"/><div><b>Not accessible</b><p>These objects could not be read with the current connection.</p></div><strong>{Number(profile.inaccessible_count??0).toLocaleString()}</strong></article></div><article><h2>Sensitive field classifications</h2>{classifications.length?<ul>{classifications.map(item=><li key={item.qualified_name}>{displayAssetName(item.qualified_name)} · {item.sensitivity_tags.map(uiCopy).join(', ')}</li>)}</ul>:<EmptyState title="No sensitive fields identified" description="Classifications appear here when profiling finds protected metadata."/>}</article><div className="actions"><Button variant="primary" onClick={() => props.navigate(`/dictionary?connection=${props.connectionId}`)}>Open Dictionary</Button><Button onClick={() => props.navigate(`/er?connection=${props.connectionId}`)}>Explore relationships</Button></div></> : loading?<EmptyState title="Profile is being prepared" description="Your profile will appear here as soon as discovery finishes."/>:<EmptyState title="Profile is not available yet" description="Run a profile from Connectors to see discovered objects and fields." action={<Button onClick={()=>props.navigate('/connectors')}>Open Connectors</Button>} />}</section>;
}

function DictionaryPage(props: { connectionId: string }) {
  const [tables, setTables] = useState<Array<{ asset_id: string; qualified_name: string; fields: Array<{ name: string; dataType: string; nullable: boolean; tags: string[]; description:string|null }> }>>([]);
  const [routines,setRoutines]=useState<Array<{qualifiedName:string;kind:string;definition:string}>>([]);
  const [summary,setSummary]=useState({tableCount:0,columnCount:0,documentedColumnCount:0,coverage:0});
  const [tab,setTab]=useState('overview');const [message,setMessage]=useState('');
  async function refresh(){const result=await api<{tables:typeof tables;routines:typeof routines;summary:typeof summary}>(`/api/connections/${props.connectionId}/dictionary`);setTables(result.tables);setRoutines(result.routines);setSummary(result.summary);}
  useEffect(()=>{void refresh();},[props.connectionId]);
  async function importFile(file?:File){if(!file)return;const format=file.name.toLowerCase().endsWith('.xlsx')?'xlsx':'csv';const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(const byte of bytes)binary+=String.fromCharCode(byte);try{const result=await api<{imported:number}>('/api/connections/'+props.connectionId+'/dictionary/import',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({format,filename:file.name,contentBase64:btoa(binary)})});setMessage(`${result.imported} descriptions imported.`);await refresh();}catch(reason){setMessage(reason instanceof Error?reason.message:'Dictionary import failed.');}}
  const standard=tables.filter(table=>!table.qualified_name.split('.').at(-1)?.startsWith('X_'));
  const custom=tables.filter(table=>table.qualified_name.split('.').at(-1)?.startsWith('X_'));
  const current=tab==='standard'?standard:tab==='custom'?custom:tables;
  return <section className="dictionary-page"><div className="page-heading"><div><p className="eyebrow">Catalog</p><h1>Dictionary</h1><p>Browse discovered tables, fields, and source descriptions.</p></div></div><article className="dictionary-summary"><div><span>Documented columns</span><strong>{summary.documentedColumnCount.toLocaleString()} / {summary.columnCount.toLocaleString()}</strong><small>{Math.round(summary.coverage*100)}% documented</small></div><div><span>Tables and views</span><strong>{summary.tableCount.toLocaleString()}</strong></div><div><span>Procedures and functions</span><strong>{routines.length.toLocaleString()}</strong></div></article><label>Import CSV or Excel dictionary<Input type="file" accept=".csv,.xlsx" aria-label="Import dictionary file" onChange={event=>void importFile(event.target.files?.[0])}/></label>{message&&<p role="status">{uiCopy(message)}</p>}<Tabs label="Dictionary categories" items={[{id:'overview',label:`Overview (${tables.length})`},{id:'standard',label:`Standard (${standard.length})`},{id:'custom',label:`Custom (${custom.length})`},{id:'routines',label:`Procedures (${routines.length})`}]} selected={tab} onSelect={setTab}/>{tab==='routines'?routines.length?<div className="dictionary-list">{routines.map(item=><details key={item.qualifiedName}><summary>{uiCopy(item.kind)} · {displayAssetName(item.qualifiedName)}</summary><pre><code>{item.definition}</code></pre></details>)}</div>:<EmptyState title="No procedures discovered" description="Source routines and their definitions will appear here when profiling discovers them."/>:current.length?<div className="dictionary-list">{current.map(table=><details key={table.asset_id}><summary>{displayAssetName(table.qualified_name)}<Badge tone="muted">{table.fields.length} fields</Badge></summary><ul>{table.fields.map(field=><li key={field.name}><strong>{displayAssetName(field.name.split('.').at(-1)??field.name)}</strong> · {uiCopy(field.dataType)}{field.nullable?' · nullable':''}{field.tags.length?` · ${field.tags.map(uiCopy).join(', ')}`:''}{field.description&&<p>{field.description}</p>}</li>)}</ul></details>)}</div>:<EmptyState title="No catalog entries yet" description="Connect and profile a source to build its dictionary." action={<Button onClick={()=>location.assign('/connectors')}>Open Connectors</Button>}/>}</section>;
}


function ControlsPage(props: { connectionId?: string; connections: Connection[]; navigate: (path:string)=>void }) {
  const [scope, setScope] = useState<Array<{ qualifiedName: string; objectType: string; scopeMode: 'profile' | 'list_only' | 'exclude' }>>([]);
  const [saved, setSaved] = useState(false);
  const [tenantSettings,setTenantSettings]=useState({allowSelfApproval:false,timeZone:'Asia/Kolkata'});
  const [tenantSettingsSaved,setTenantSettingsSaved]=useState(false);
  const [sso,setSso]=useState({issuer:'',clientId:'',clientSecretRef:'',allowedEmailDomains:'',enabled:false});const [ssoStatus,setSsoStatus]=useState('');
  useEffect(() => { if(props.connectionId)void api<{ scope: typeof scope }>(`/api/connections/${props.connectionId}/scope`).then(result => setScope(result.scope)); }, [props.connectionId]);
  useEffect(()=>{void api<typeof tenantSettings>('/api/tenant/settings').then(setTenantSettings);},[]);
  useEffect(()=>{void api<{provider:{issuer:string;clientId:string;clientSecretRef:string;allowedEmailDomains:string[];enabled:boolean}|null}>('/api/tenant/sso').then(result=>{if(result.provider)setSso({...result.provider,allowedEmailDomains:result.provider.allowedEmailDomains.join(', ')});});},[]);
  async function save() { if(!props.connectionId)return;await api(`/api/connections/${props.connectionId}/scope`, { method: 'PUT', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ rules: scope }) }); setSaved(true); }
  async function saveTenantSettings(){await api('/api/tenant/settings',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(tenantSettings)});setTenantSettingsSaved(true);}
  async function saveSso(event:React.FormEvent){event.preventDefault();setSsoStatus('');try{await api('/api/tenant/sso',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({...sso,allowedEmailDomains:sso.allowedEmailDomains.split(',').map(domain=>domain.trim()).filter(Boolean)})});setSsoStatus('SSO settings saved. The client secret remains in the server secret store.');}catch(reason){setSsoStatus(reason instanceof Error?reason.message:'SSO settings could not be saved.');}}
  const current=props.connections.find(item=>item.connectionId===props.connectionId);
  return <section className="controls-page">
    <div className="page-heading"><div><h1>Controls{current?` · ${connectionDisplayName(current)}`:''}</h1><p>What each connector may profile, list, and use to answer questions. Anything left out is never sampled or queried.</p></div><label>Connector<Select aria-label="Controls connector" value={props.connectionId??''} onChange={event=>props.navigate(`/controls?connection=${encodeURIComponent(event.target.value)}`)}><option value="">Choose a connector</option>{props.connections.filter(item=>item.status==='active').map(item=><option key={item.connectionId} value={item.connectionId}>{connectionDisplayName(item)}</option>)}</Select></label></div>
    {props.connectionId&&<article><div className="page-heading"><div><h2>What to include</h2><p>Scope only narrows the source's read-only login. It never widens access.</p></div></div>{scope.length?scope.map(rule=><div className="scope-row" key={rule.qualifiedName}><span>{displayAssetName(rule.qualifiedName)}</span><label>Access for this object<Select aria-label={`Scope for ${displayAssetName(rule.qualifiedName)}`} value={rule.scopeMode} onChange={event=>setScope(current=>current.map(item=>item.qualifiedName===rule.qualifiedName?{...item,scopeMode:event.target.value as typeof item.scopeMode}:item))}><option value="profile">Profile and query</option><option value="list_only">List only</option><option value="exclude">Exclude</option></Select></label></div>):<p>No object-specific rules are set. New objects follow the source default and appear here after profiling.</p>}<div className="actions"><Button variant="primary" onClick={() => void save()} disabled={!props.connectionId}>Save scope</Button>{saved&&<Badge tone="good">Scope saved</Badge>}</div></article>}
    <article><h2>Tenant settings</h2><label>Tenant time zone<Input aria-label="Tenant time zone" value={tenantSettings.timeZone} onChange={event=>setTenantSettings({...tenantSettings,timeZone:event.target.value})} /></label><label className="checkbox-label"><Input type="checkbox" checked={tenantSettings.allowSelfApproval} onChange={event=>setTenantSettings({...tenantSettings,allowSelfApproval:event.target.checked})} />Allow self-approval</label><p>Off by default. If enabled, approvals by the definition owner are recorded as self-approved.</p><Button variant="primary" onClick={()=>void saveTenantSettings()}>Save tenant settings</Button>{tenantSettingsSaved&&<p role="status">Tenant settings saved.</p>}</article>
    <article><h2>Organization single sign-on</h2><p>Password sign-in remains available for account recovery. The client secret is resolved by the API from its secret store; enter only its reference here.</p><form onSubmit={event=>void saveSso(event)}><label>OIDC issuer<Input aria-label="OIDC issuer" type="url" required value={sso.issuer} onChange={event=>setSso({...sso,issuer:event.target.value})} /></label><label>Client ID<Input aria-label="OIDC client ID" required value={sso.clientId} onChange={event=>setSso({...sso,clientId:event.target.value})} /></label><label>Client secret reference<Input aria-label="OIDC client secret reference" required value={sso.clientSecretRef} onChange={event=>setSso({...sso,clientSecretRef:event.target.value})} /></label><label>Allowed email domains<Input aria-label="Allowed email domains" required value={sso.allowedEmailDomains} onChange={event=>setSso({...sso,allowedEmailDomains:event.target.value})} /></label><label className="checkbox-label"><Input type="checkbox" checked={sso.enabled} onChange={event=>setSso({...sso,enabled:event.target.checked})} />Enable organization sign-in</label><Button type="submit">Save sign-in settings</Button></form>{ssoStatus&&<p role="status">{ssoStatus}</p>}</article>
  </section>;
}

type AnalyticRun = { runId: string; state: string; stateVersion:number; planHash?:string; plan: { question: string; steps: Array<{ source_id: string; agent_id: string }> }; answer: { answer: { claims?: Array<{ statement: string; evidence_ids: string[] }>; evidence?: Array<{ evidence_id: string; locator: string; redacted_summary: string }>; bySource?: Array<{ value: number; sourceId?: string }> }; presentation: { title: string; layout: string } } | null };

function AnalyticWorkspace(props: { connections: Connection[]; navigate: (path: string) => void; runId?:string|undefined; notifications: Notification[]; recentQuestions:Array<{planId:string;question:string}>; markRead:(id:string)=>Promise<void>; userName:string }) {
  const [question,setQuestion]=useState('');const [selected,setSelected]=useState<string[]>([]);const [authorized,setAuthorized]=useState<string[]>([]);const [run,setRun]=useState<AnalyticRun|null>(null);const [events,setEvents]=useState<Array<{sequence:number;event_type:string}>>([]);const [error,setError]=useState('');const [feedback,setFeedback]=useState('');const [catalogueMatches,setCatalogueMatches]=useState<string[]|null>(null);
  const active=props.connections.filter(item=>item.status==='active'&&authorized.includes(item.connectionId));
  useEffect(()=>{void api<{sources:Array<{id:string}>}>('/api/analytic/sources').then(result=>{const ids=result.sources.map(item=>item.id);setAuthorized(ids);setSelected(ids);}).catch(()=>setError('Authorized sources could not be loaded.'));},[]);
  useEffect(()=>{if(props.runId)void api<AnalyticRun>(`/api/runs/${props.runId}`).then(setRun).catch(()=>setError('Saved run could not be loaded.'));},[props.runId]);
  useEffect(()=>{if(!run)return;const after=events.at(-1)?.sequence??0;void api<{events:Array<{sequence:number;event_type:string}>}>(`/api/runs/${run.runId}/events?after=${after}`).then(result=>{if(result.events.length)setEvents(previous=>[...previous,...result.events]);}).catch(()=>setError('Run events could not be resumed.'));},[run?.runId,run?.stateVersion]);
  useEffect(()=>{if(run&&!['COMPLETED','PARTIAL','FAILED','CANCELLED','POLICY_BLOCKED'].includes(run.state)){const timer=setTimeout(()=>{void api<AnalyticRun>(`/api/runs/${run.runId}`).then(setRun).catch(()=>setError('Run status could not be refreshed.'));},600);return()=>clearTimeout(timer);}},[run]);
  useEffect(()=>{if(!run)return;requestAnimationFrame(()=>{const scroll=document.querySelector('.chat-scroll');if(scroll)scroll.scrollTop=scroll.scrollHeight;});},[run?.runId,run?.stateVersion]);
  async function ask(){setError('');setFeedback('');setCatalogueMatches(null);try{if(/\b(?:table|view)[_. -]?\d+\b/i.test(question)){const result=await api<{matches:string[]}>('/api/catalogue/search?q='+encodeURIComponent(question));setCatalogueMatches(result.matches);setQuestion('');return;}const result=await api<{runId:string}>('/api/runs',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({question,sourceIds:selected})});props.navigate(`/runs/${result.runId}`);const detail=await api<AnalyticRun>(`/api/runs/${result.runId}`);setRun(detail);setEvents([]);}catch(reason){setError(reason instanceof Error?reason.message:'Question could not be started.');}}
  async function rate(verdict:'useful'|'not_useful'){if(!run)return;try{await api(`/api/runs/${run.runId}/feedback`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({verdict})});setFeedback('Feedback saved to your personal agent.');}catch(reason){setError(reason instanceof Error?reason.message:'Feedback could not be saved.');}}
  async function exportPack(format:'pdf'|'xlsx'|'pptx'){if(!run)return;try{const response=await fetch(`/api/runs/${run.runId}/evidence-pack`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({format})});if(!response.ok)throw new Error('Evidence pack could not be exported.');const blob=await response.blob();const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`evidence-${run.runId}.${format}`;link.click();URL.revokeObjectURL(link.href);}catch(reason){setError(reason instanceof Error?reason.message:'Evidence pack could not be exported.');}}
  const friendlySource=(sourceId:string)=>connectionDisplayName(props.connections.find(item=>item.connectionId===sourceId)??{connectionId:sourceId,connectorType:'',displayName:'',status:'',agentId:null,lastJobState:null});
  const friendly=(value:string)=>uiCopy(value.replace(/\b(?:run_state_changed|run_created|evidence_added|plan_validated|run_terminal)\b/gi,''));
  const markAllRead=()=>Promise.all(props.notifications.filter(item=>!item.readAt).map(item=>props.markRead(item.notificationId))).then(()=>undefined).catch(()=>setError('Notifications could not be updated.'));
  return <section className="analytic-workspace"><div className="chat-shell"><div className="chat-scroll">
    <div className="hello"><Logo /><h1>Good afternoon{props.userName?`, ${props.userName}`:''}</h1><p>{props.notifications.filter(item=>!item.readAt).length?`${props.notifications.filter(item=>!item.readAt).length} new updates since your last visit.`:'What would you like to understand today?'}</p></div>
    {!run&&props.notifications.length>0&&<div className="home-updates"><div className="home-updates-head"><Logo /><strong>While you were away</strong><Button variant="ghost" size="small" onClick={()=>void markAllRead()}>Mark all as read</Button></div>{props.notifications.slice(0,3).map(item=>{const {title,detail}=notificationCopy(item);return <article className="home-notice" key={item.notificationId}><span className="notice-mark" aria-hidden="true">•</span><div><b>{title}</b><p>{detail}</p><small>{item.readAt?'Earlier update':'New update'}</small></div><Button size="small" onClick={()=>props.navigate('/approval-matrix')}>View details</Button></article>;})}</div>}
    {!run&&props.recentQuestions.length>0&&<div className="prompts">{props.recentQuestions.slice(0,3).map(item=><Button key={item.planId} variant="secondary" onClick={()=>setQuestion(friendly(item.question))}>{friendly(item.question)}</Button>)}</div>}
    <div className="chat-thread">{catalogueMatches&&<div className="assistant-row"><Logo className="assistant-logo" /><article className="evidence-card"><h2>Catalog results</h2>{catalogueMatches.length?catalogueMatches.map(name=><p key={name}>{displayAssetName(name)}</p>):<p>No matching catalog entries.</p>}</article></div>}{run&&<><div className="question-bubble">{friendly(run.plan.question)}</div><div className="assistant-row"><Logo className="assistant-logo" /><div className="stack"><article className="plan-card"><div className="row"><h2>How your question is being answered</h2><Badge tone={run.state==='COMPLETED'?'good':'primary'}>{run.state==='COMPLETED'?'Completed':run.state==='POLICY_BLOCKED'?'Needs review':run.state==='FAILED'?'Could not complete':'In progress'}</Badge></div><p>{run.plan.steps.length} read-only steps across your selected sources.</p><ol>{run.plan.steps.map((step,index)=><li key={`${step.source_id}-${index}`}>{friendlySource(step.source_id)} · Read metadata</li>)}</ol></article>{run.answer&&<article className="evidence-card"><h2>{friendly(run.answer.presentation.title)}</h2>{run.answer.answer.claims?.filter((claim,index,claims)=>claims.findIndex(item=>item.statement===claim.statement)===index).map((claim,index)=><p className="answer-claim" key={index}>{friendly(claim.statement)}</p>)}{run.answer.answer.bySource?.map((item,index)=><p key={index}>Source result: {item.value}</p>)}<div className="evidence-list"><b>Evidence</b>{run.answer.answer.evidence?.map(item=><div key={item.evidence_id}><span>{friendly(item.locator||'Source metadata')}</span><small>{friendly(item.redacted_summary)}</small></div>)}</div><p><Badge tone="good">Evidence-backed · read-only</Badge></p>{run.state==='COMPLETED'&&<div className="export-actions" aria-label="Export evidence pack"><Button size="small" onClick={()=>void exportPack('pdf')}>Export PDF</Button><Button size="small" onClick={()=>void exportPack('xlsx')}>Export workbook</Button><Button size="small" onClick={()=>void exportPack('pptx')}>Export slides</Button></div>}<div className="feedback-actions"><span>Was this answer helpful?</span><Button variant="ghost" aria-label="Useful" onClick={()=>void rate('useful')}>👍</Button><Button variant="ghost" aria-label="Not useful" onClick={()=>void rate('not_useful')}>👎</Button></div>{feedback&&<p role="status">{feedback}</p>}</article>}</div></div></>}</div></div>
    {active.length===0&&!props.runId&&<EmptyState title="Connect a source to get started" description="Ask questions across your connected data, with a read-only plan and evidence for each answer." action={<Button variant="primary" onClick={()=>props.navigate('/connectors')}>Add a connector</Button>} />}
    {error&&<p role="alert" className="error">{error}</p>}
    <form className="composer" onSubmit={event=>{event.preventDefault();void ask();}}><Textarea aria-label="Ask a question" required value={question} onChange={event=>setQuestion(event.target.value)} placeholder="Ask anything about your data…" rows={2} /><div className="composer-footer"><details className="source-picker"><summary>All sources</summary>{active.map(item=><label key={item.connectionId}><Input type="checkbox" data-source-id={item.connectionId} checked={selected.includes(item.connectionId)} onChange={event=>setSelected(old=>event.target.checked?[...old,item.connectionId]:old.filter(id=>id!==item.connectionId))} />{friendlySource(item.connectionId)}</label>)}</details><Button type="button" variant="ghost" aria-label="Attach a file" disabled title="File uploads are not available in this workspace">⌁</Button><Button variant="primary" type="button" aria-label="Send question" disabled={!question.trim()||(!selected.length&&!/\b(?:table|view)[_. -]?\d+\b/i.test(question))} onClick={()=>void ask()}>➜</Button></div></form><p className="hint">Analytic mode · read-only. Every answer shows its evidence, sources and lineage.</p></div></section>;
}

function AgentGroups(props:{connections:Connection[]}){
  const [groups,setGroups]=useState<Array<{groupId:string;version:number;connectionId:string;connectorType:string}>>([]);const [target,setTarget]=useState<Record<string,string>>({});const [error,setError]=useState('');
  async function reload(){const result=await api<{groups:typeof groups}>('/api/agents');setGroups(result.groups);}
  useEffect(()=>{void reload().catch(()=>setError('Agent groups could not be loaded.'));},[]);
  const unique=[...new Map(groups.map(group=>[group.groupId,group])).values()];
  const active=props.connections.filter(item=>item.status==='active');
  const buckets=[
    {name:'Database and workbook sources',items:active.filter(item=>['postgres','sql_server','excel'].includes(item.connectorType))},
    {name:'Cloud and transformation sources',items:active.filter(item=>['snowflake','dbt'].includes(item.connectorType))},
    {name:'Reports and dashboards',items:active.filter(item=>['tableau','power_bi'].includes(item.connectorType))},
  ].filter(bucket=>bucket.items.length);
  return <><article className="agent-map"><div className="agent-map-node agent-map-user"><strong>Your agent</strong><span>Learns your preferences</span></div><span className="agent-map-arrow" aria-hidden="true">↓</span><div className="agent-map-node"><strong>Orchestrator agent</strong><span>Plans and routes every question</span></div><span className="agent-map-arrow" aria-hidden="true">↓</span><div className="agent-map-groups">{buckets.map(bucket=><section className="agent-map-group" key={bucket.name}><h3>{bucket.name}</h3>{bucket.items.map(connection=><div className="agent-map-source" key={connection.connectionId}><strong>{connectionDisplayName(connection)}</strong><span>{connectorTypeLabel(connection.connectorType)}</span></div>)}</section>)}</div><div className="agent-map-special"><div><strong>Identifier agent</strong><span>Matches identifiers across connected sources</span></div><div><strong>ID trace agent</strong><span>Follows protected identifier paths</span></div></div></article><article><h2>Source groups</h2>{groups.map(group=><div key={group.connectionId}><span>{connectorTypeLabel(group.connectorType)} · version {group.version}</span><label>Move to<Select aria-label={`Move ${connectorTypeLabel(group.connectorType)} source group`} value={target[group.connectionId]??''} onChange={event=>setTarget({...target,[group.connectionId]:event.target.value})}><option value="">Choose a group</option>{unique.filter(item=>item.groupId!==group.groupId).map((item,index)=><option key={item.groupId} value={item.groupId}>Group {index+1} · version {item.version}</option>)}</Select></label><Button disabled={!target[group.connectionId]} onClick={async()=>{try{await api(`/api/groups/${target[group.connectionId]}/members/${group.connectionId}`,{method:'POST'});await reload();}catch{setError('Source group could not be changed.');}}}>Move source</Button></div>)}{groups.length===0&&<EmptyState title="No source groups yet" description="Connect and profile data sources to organize them for analysis."/>}{error&&<p role="alert">{error}</p>}</article></>;
}

type GovernedReport = {reportId:string;name:string;governedId:string;version:number;latestSnapshotId:string|null;latestRunId:string|null;latestSnapshotAt:string|null};
function ReportsPage(){
  const [reports,setReports]=useState<GovernedReport[]>([]);const [governed,setGoverned]=useState<Array<{governedId:string;name:string;version:number;approvedBy:string|null}>>([]);const [schedules,setSchedules]=useState<Array<{scheduleId:string;reportId:string;localTime:string;cadence:'daily'|'weekly';weekday:number|null;timeZone:string;nextRunAt:string;enabled:boolean}>>([]);const [scheduleTimes,setScheduleTimes]=useState<Record<string,string>>({});const [cadences,setCadences]=useState<Record<string,'daily'|'weekly'>>({});const [weekdays,setWeekdays]=useState<Record<string,number>>({});const [name,setName]=useState('');const [governedVersion,setGovernedVersion]=useState('');const [localTime]=useState('06:00');const [message,setMessage]=useState('');const [error,setError]=useState('');
  async function reload(){const [reportData,agentData,scheduleData]=await Promise.all([api<{reports:GovernedReport[]}>('/api/me/reports'),api<{governed:typeof governed}>('/api/agents'),api<{schedules:typeof schedules}>('/api/me/schedules')]);setReports(reportData.reports);setGoverned(agentData.governed.filter(item=>item.approvedBy));setSchedules(scheduleData.schedules);}
  useEffect(()=>{void reload().catch(()=>setError('Reports could not be loaded.'));},[]);
  async function create(){const [governedId,version]=governedVersion.split(':');if(!governedId||!version)return;try{await api('/api/me/reports',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name,governedId,version:Number(version)})});setName('');setMessage('Governed report saved.');await reload();}catch(reason){setError(reason instanceof Error?reason.message:'Report could not be saved.');}}
  async function download(reportId:string,format:'pdf'|'xlsx'|'pptx'){try{const response=await fetch(`/api/me/reports/${reportId}/exports/${format}`);if(!response.ok)throw new Error((await response.json()).error??'Report export is not available yet.');const blob=await response.blob();const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`report.${format}`;link.click();URL.revokeObjectURL(link.href);}catch(reason){setError(reason instanceof Error?reason.message:'Report could not be exported.');}}
  return <section className="reports-page"><h1>Reports</h1><p>Governed reports use an approved definition version. Each run keeps its evidence snapshot.</p><article><h2>Create a governed report</h2><label>Report name<Input value={name} onChange={event=>setName(event.target.value)} /></label><label>Approved definition<Select value={governedVersion} onChange={event=>setGovernedVersion(event.target.value)}><option value="">Choose an approved version</option>{governed.map(item=><option key={`${item.governedId}:${item.version}`} value={`${item.governedId}:${item.version}`}>{uiCopy(item.name)} · version {item.version}</option>)}</Select></label><Button disabled={!name.trim()||!governedVersion} onClick={()=>void create()}>Save report</Button></article><article><h2>Governed reports</h2>{reports.map(report=>{const schedule=schedules.find(item=>item.reportId===report.reportId);const cadence=cadences[report.reportId]??schedule?.cadence??'daily';return <div className="report-card" key={report.reportId}><h3>{uiCopy(report.name)}</h3><p>Approved version {report.version} · {report.latestSnapshotId?`Last run ${report.latestSnapshotAt ? new Date(report.latestSnapshotAt).toLocaleString() : 'No completed run yet'}`:'No completed run yet'}</p><div className="report-actions"><Button onClick={async()=>{try{await api(`/api/me/reports/${report.reportId}/run`,{method:'POST'});setMessage('Report run started.');}catch(reason){setError(reason instanceof Error?reason.message:'Report run could not start.');}}}>Run report</Button>{report.latestSnapshotId&&<><Button onClick={()=>void download(report.reportId,'pdf')}>Download PDF</Button><Button onClick={()=>void download(report.reportId,'xlsx')}>Download workbook</Button><Button onClick={()=>void download(report.reportId,'pptx')}>Download slides</Button></>}</div><label>Schedule cadence<Select aria-label={`Schedule cadence for ${uiCopy(report.name)}`} value={cadence} onChange={event=>setCadences({...cadences,[report.reportId]:event.target.value as 'daily'|'weekly'})}><option value="daily">Daily</option><option value="weekly">Weekly</option></Select></label>{cadence==='weekly'&&<label>Weekday<Select aria-label={`Schedule weekday for ${uiCopy(report.name)}`} value={weekdays[report.reportId]??schedule?.weekday??1} onChange={event=>setWeekdays({...weekdays,[report.reportId]:Number(event.target.value)})}><option value={1}>Monday</option><option value={2}>Tuesday</option><option value={3}>Wednesday</option><option value={4}>Thursday</option><option value={5}>Friday</option><option value={6}>Saturday</option><option value={7}>Sunday</option></Select></label>}<label>Local time<Input aria-label={`${cadence==='weekly'?'Weekly':'Daily'} schedule for ${uiCopy(report.name)}`} type="time" value={scheduleTimes[report.reportId]??schedule?.localTime??localTime} onChange={event=>setScheduleTimes({...scheduleTimes,[report.reportId]:event.target.value})} /></label><p>Times shown in the tenant time zone{schedule?.timeZone?` (${schedule.timeZone})`:''}; schedule instants are stored in UTC.</p><div className="report-actions"><Button onClick={async()=>{try{await api('/api/me/schedules',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({reportId:report.reportId,localTime:scheduleTimes[report.reportId]??schedule?.localTime??localTime,cadence,...(cadence==='weekly'?{weekday:weekdays[report.reportId]??schedule?.weekday??1}:{})})});setMessage(cadence==='weekly'?'Weekly schedule saved.':'Daily schedule saved.');await reload();}catch(reason){setError(reason instanceof Error?reason.message:'Schedule could not be saved.');}}}>{schedule?.enabled?`Update ${cadence} schedule`:`Schedule ${cadence}`}</Button>{schedule?.enabled&&<Button onClick={async()=>{try{await api(`/api/me/schedules/${schedule.scheduleId}`,{method:'DELETE'});setMessage('Schedule disabled.');await reload();}catch(reason){setError(reason instanceof Error?reason.message:'Schedule could not be disabled.');}}}>Disable schedule</Button>}</div></div>;})}{reports.length===0&&<p>No governed reports yet.</p>}</article>{error&&<p role="alert" className="error">{error}</p>}{message&&<p role="status">{uiCopy(message)}</p>}</section>;
}

function AgentsPage(props:{connections:Connection[]}){
  const [memory,setMemory]=useState<{vocabulary:Record<string,string>;defaultSources:string[];answerStyle:string|null}>({vocabulary:{},defaultSources:[],answerStyle:'concise'});const [governed,setGoverned]=useState<Array<{governedId:string;name:string;version:number;approvedBy:string|null}>>([]);const [savedQuestions,setSavedQuestions]=useState<Array<{planId:string;question:string;createdAt:string}>>([]);const [name,setName]=useState('');const [question,setQuestion]=useState('');const [sources,setSources]=useState<string[]>([]);const [draft,setDraft]=useState<{governedId:string;version:number}|null>(null);const [message,setMessage]=useState('');const [error,setError]=useState('');
  async function loadGoverned(){const result=await api<{governed:typeof governed}>('/api/agents');setGoverned(result.governed);}
  async function loadSavedQuestions(){const result=await api<{questions:typeof savedQuestions}>('/api/me/saved-questions');setSavedQuestions(result.questions);}
  useEffect(()=>{void Promise.all([api<{memory:typeof memory}>('/api/me/agent'),api<{sources:Array<{id:string}>}>('/api/analytic/sources'),api<{governed:typeof governed}>('/api/agents'),api<{questions:typeof savedQuestions}>('/api/me/saved-questions')]).then(([saved,connected,agentData,questions])=>{setMemory(saved.memory);setSources(connected.sources.map(item=>item.id));setGoverned(agentData.governed);setSavedQuestions(questions.questions);}).catch(()=>setError('Agent settings could not be loaded.'));},[]);
  async function save(){try{const result=await api<{memory:typeof memory}>('/api/me/agent',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(memory)});setMemory(result.memory);setMessage('Personal agent settings saved.');}catch(reason){setError(reason instanceof Error?reason.message:'Settings could not be saved.');}}
  async function create(){try{const result=await api<{governedId:string;version:number}>('/api/governed-agents',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name,question,sourceIds:sources})});setDraft(result);setMessage(`Draft version ${result.version} saved. A different tenant member must approve it.`);await loadGoverned();}catch(reason){setError(reason instanceof Error?reason.message:'Draft could not be saved.');}}
  async function approve(){if(!draft)return;try{await api(`/api/governed-agents/${draft.governedId}/approve`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({version:draft.version})});setMessage(`Version ${draft.version} approved.`);}catch(reason){setError(reason instanceof Error?reason.message:'Approval requires a different member.');}}
  async function rerun(){if(!draft)return;try{const result=await api<{runId:string}>(`/api/governed-agents/${draft.governedId}/runs`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({version:draft.version})});setMessage(`Governed run ${result.runId} started.`);}catch(reason){setError(reason instanceof Error?reason.message:'Governed run could not be started.');}}
  return <section><h1>Agents</h1><p>Personal settings shape presentation only. Governed definitions are immutable by version.</p><AgentGroups connections={props.connections}/><article><h2>My agent</h2><label>Answer style<Select value={memory.answerStyle??'concise'} onChange={event=>setMemory({...memory,answerStyle:event.target.value})}><option value="concise">Concise</option><option value="detailed">Detailed</option><option value="sql_first">SQL first</option><option value="lineage_first">Lineage first</option></Select></label><label>Vocabulary term<Input id="vocabulary-term" /></label><label>Meaning<Input id="vocabulary-meaning" /></label><Button onClick={()=>{const term=(document.getElementById('vocabulary-term') as HTMLInputElement).value;const meaning=(document.getElementById('vocabulary-meaning') as HTMLInputElement).value;if(term&&meaning){const updated={...memory,vocabulary:{...memory.vocabulary,[term]:meaning}};setMemory(updated);void api('/api/me/agent',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(updated)}).then(()=>setMessage('Personal agent settings saved.')).catch(()=>setError('Settings could not be saved.'));}else void save();}}>Save my agent</Button><Button onClick={async()=>{await api('/api/me/agent',{method:'DELETE'});setMemory({vocabulary:{},defaultSources:[],answerStyle:null});setSavedQuestions([]);setMessage('Personal memory deleted.');}}>Delete my memory</Button><h3>Saved questions</h3><p>Saved only after you accepted the answer. Reuse one as the starting plan for another run.</p>{savedQuestions.map(item=><div className="saved-question" key={item.planId}><p>{item.question}</p><Button onClick={async()=>{try{const result=await api<{runId:string}>(`/api/me/saved-questions/${item.planId}/start`,{method:'POST'});location.assign('/runs/'+result.runId);}catch(reason){setError(reason instanceof Error?reason.message:'Saved question could not be started.');}}}>Start from this plan</Button><Button onClick={async()=>{try{await api(`/api/me/saved-questions/${item.planId}`,{method:'DELETE'});await loadSavedQuestions();}catch(reason){setError(reason instanceof Error?reason.message:'Saved question could not be removed.');}}}>Remove</Button></div>)}{savedQuestions.length===0&&<p>No saved questions yet.</p>}</article><article><h2>Governed definition</h2><label>Name<Input value={name} onChange={event=>setName(event.target.value)} /></label><label>Question<Input value={question} onChange={event=>setQuestion(event.target.value)} /></label><Button disabled={!name||!question||!sources.length} onClick={()=>void create()}>Save draft version</Button>{draft&&<><p>Draft saved · version {draft.version}</p><Button onClick={()=>void approve()}>Approve version</Button><Button onClick={()=>void rerun()}>Run approved version</Button></>}</article><article><h2>Saved governed versions</h2>{governed.map(item=><div key={`${item.governedId}-${item.version}`}><p>{uiCopy(item.name)} · version {item.version} · {item.approvedBy?'Approved':'Awaiting approval'}</p>{item.approvedBy&&<Button onClick={async()=>{try{await api(`/api/governed-agents/${item.governedId}/runs`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({version:item.version})});setMessage('Governed run started.');}catch(reason){setError(reason instanceof Error?reason.message:'Governed run could not be started.');}}}>Run version {item.version}</Button>}</div>)}</article>{error&&<p role="alert" className="error">{error}</p>}{message&&<p role="status">{message}</p>}</section>;
}

function MyAgentPage(){
  const [memory,setMemory]=useState<{vocabulary:Record<string,string>;defaultSources:string[];answerStyle:string|null}>({vocabulary:{},defaultSources:[],answerStyle:'concise'});
  const [questions,setQuestions]=useState<Array<{planId:string;question:string;createdAt:string}>>([]);
  const [term,setTerm]=useState('');const [meaning,setMeaning]=useState('');const [message,setMessage]=useState('');
  async function refresh(){const [saved,personal]=await Promise.all([api<{memory:typeof memory}>('/api/me/agent'),api<{questions:typeof questions}>('/api/me/saved-questions')]);setMemory(saved.memory);setQuestions(personal.questions);}
  useEffect(()=>{void refresh().catch(()=>setMessage('Your agent settings could not be loaded.'));},[]);
  async function save(){try{const vocabulary=term.trim()&&meaning.trim()?{...memory.vocabulary,[term.trim()]:meaning.trim()}:memory.vocabulary;const updated={...memory,vocabulary};await api('/api/me/agent',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(updated)});setMemory(updated);setTerm('');setMeaning('');setMessage('Your preferences were saved.');}catch{setMessage('Your preferences could not be saved.');}}
  async function remove(planId:string){try{await api(`/api/me/saved-questions/${planId}`,{method:'DELETE'});await refresh();setMessage('Saved question removed.');}catch{setMessage('Saved question could not be removed.');}}
  return <section className="my-agent-page"><div className="page-heading"><div><p className="eyebrow">Personal workspace</p><h1>My agent</h1><p>Shape how answers are presented and reuse questions you have saved.</p></div></div><article><h2>Answer preferences</h2><label>Answer style<Select value={memory.answerStyle??'concise'} onChange={event=>setMemory({...memory,answerStyle:event.target.value})}><option value="concise">Concise</option><option value="detailed">Detailed</option><option value="sql_first">Source first</option><option value="lineage_first">Evidence first</option></Select></label><label>Vocabulary term<Input value={term} onChange={event=>setTerm(event.target.value)} placeholder="A word your team uses" /></label><label>Meaning<Input value={meaning} onChange={event=>setMeaning(event.target.value)} placeholder="How your agent should interpret it" /></label><div className="actions"><Button variant="primary" onClick={()=>void save()}>Save preferences</Button><Button onClick={async()=>{try{await api('/api/me/agent',{method:'DELETE'});setMemory({vocabulary:{},defaultSources:[],answerStyle:null});setQuestions([]);setMessage('Personal memory cleared.');}catch{setMessage('Personal memory could not be cleared.');}}}>Clear personal memory</Button></div></article><article><h2>Saved questions</h2><p>Questions you marked useful are ready to run again.</p>{questions.length?questions.map(item=><div className="saved-question" key={item.planId}><p>{item.question}</p><div className="actions"><Button onClick={async()=>{try{const result=await api<{runId:string}>(`/api/me/saved-questions/${item.planId}/start`,{method:'POST'});location.assign(`/runs/${result.runId}`);}catch{setMessage('Saved question could not be started.');}}}>Start from this question</Button><Button variant="ghost" onClick={()=>void remove(item.planId)}>Remove</Button></div></div>):<EmptyState title="No saved questions yet" description="Mark a helpful answer to keep its question here for next time."/>}{message&&<p role="status">{message}</p>}</article></section>;
}

function ApprovalMatrix() {
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [governed,setGoverned]=useState<Array<{governedId:string;name:string;ownerId:string;version:number;approvedBy:string|null}>>([]);const [evaluation,setEvaluation]=useState<{count:number;questionIds:string[]}>({count:0,questionIds:[]});const [message,setMessage]=useState('');
  const [flowspecs,setFlowspecs]=useState<Array<{flowspecId:string;latestVersion:number;subjectHash:string|null;approvalStatus:string|null}>>([]);
  const [assertions,setAssertions]=useState<Array<{assertion_id:string;from_name:string;to_name:string;evidence_method:string;review_status:string;verification:string;confidence_score:number|null;evidence_count:number}>>([]);
  async function refresh(){const [agentData,assertionData,flowData]=await Promise.all([api<{governed:typeof governed}>('/api/agents'),api<{assertions:typeof assertions}>('/api/lineage/assertions'),api<{flowspecs:typeof flowspecs}>('/api/flowspecs')]);setGoverned(agentData.governed);setAssertions(assertionData.assertions);setFlowspecs(flowData.flowspecs);void api<typeof evaluation>('/api/evaluation').then(setEvaluation).catch(()=>setEvaluation({count:0,questionIds:[]}));void api<{notifications:Notification[]}>('/api/notifications').then(result=>setNotifications(result.notifications)).catch(()=>setNotifications([]));}
  useEffect(() => { void refresh(); }, []);
  const latestNightly=notifications.find(item=>item.type==='nightly');
  return <section><div className="page-heading"><div><p className="eyebrow">Review and approve</p><h1>Approval matrix</h1><p>Review changes and evidence before they affect answers.</p></div></div>{latestNightly?<article className="nightly-summary"><div><h2>Latest overnight profile</h2><p>{Number(latestNightly.summary.profiled??0).toLocaleString()} objects profiled from {Number(latestNightly.summary.listed??0).toLocaleString()} listed.</p></div><Badge tone={notifications.some(item=>!item.readAt)?'warn':'good'}>{notifications.filter(item=>!item.readAt).length} new findings</Badge><div className="nightly-stats"><div><strong>{assertions.length}</strong><span>Lineage links to review</span></div><div><strong>{flowspecs.filter(item=>item.approvalStatus==='pending').length+governed.filter(item=>!item.approvedBy).length}</strong><span>Approvals waiting</span></div><div><strong>{notifications.length}</strong><span>Recent updates</span></div></div></article>:<EmptyState title="No overnight profile yet" description="Findings and review items appear here after a scheduled profile has run."/>}<article><h2>Lineage assertions</h2>{assertions.map(item=><div className="assertion-row" key={item.assertion_id}><p>{displayAssetName(item.from_name)} → {displayAssetName(item.to_name)}</p><p>{uiCopy(item.evidence_method)} · {uiCopy(item.review_status)} · Verification: {uiCopy(item.verification)} · {item.evidence_count} evidence item(s)</p>{item.review_status==='unreviewed'&&<Button onClick={async()=>{try{await api(`/api/lineage/assertions/${item.assertion_id}/review`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({status:'accepted'})});setMessage('Assertion accepted; verification was not changed.');await refresh();}catch(reason){setMessage(reason instanceof Error?reason.message:'Review failed.');}}}>Accept assertion</Button>}</div>)}{assertions.length===0&&<p>No assertions await review.</p>}</article><article><h2>Approval handoffs</h2>{flowspecs.map(item=><div key={item.flowspecId}><p>Approval handoff · version {item.latestVersion} · {uiCopy(item.approvalStatus??'No approval')}</p>{item.approvalStatus==='pending'&&<Button onClick={async()=>{try{await api(`/api/flowspecs/${item.flowspecId}/approve`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({version:item.latestVersion})});setMessage(`Handoff version ${item.latestVersion} approved.`);await refresh();}catch(reason){setMessage(reason instanceof Error?reason.message:'A different member must approve this handoff.');}}}>Approve version {item.latestVersion}</Button>}</div>)}{flowspecs.length===0&&<p>No approval handoffs await review.</p>}</article><article><h2>Governed definitions</h2>{governed.map(item=><div key={`${item.governedId}-${item.version}`}><p>{uiCopy(item.name)} · version {item.version} · {item.approvedBy?'Approved':'Awaiting approval'}</p>{!item.approvedBy&&<Button onClick={async()=>{try{await api(`/api/governed-agents/${item.governedId}/approve`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({version:item.version})});setMessage(`Version ${item.version} approved.`);await refresh();}catch(reason){setMessage(reason instanceof Error?reason.message:'Approval failed.');}}}>Approve version {item.version}</Button>}</div>)}{governed.length===0&&<p>No governed definitions yet.</p>}</article><article><h2>Evaluation set</h2><p>{evaluation.count} evaluation cases</p></article><p role="status">{uiCopy(message)}</p><h2>Notifications</h2>{notifications.length===0?<p>No findings yet.</p>:<ul>{notifications.map(item=><li key={item.notificationId}>{notificationCopy(item).title} · {item.readAt?'Earlier':'New'}</li>)}</ul>}</section>;
}

function NotificationPanel(props: { notifications: Notification[]; close: () => void; markRead: (id: string) => Promise<void> }) {
  const label=(item:Notification)=>notificationCopy(item).title;
  return <aside className="notification-panel" aria-label="Notifications"><div className="page-heading"><h2>Notifications</h2><Button aria-label="Close notifications" onClick={props.close}>×</Button></div><h3>New</h3>{props.notifications.filter(item => !item.readAt).map(item => <Button className="notification-item" key={item.notificationId} onClick={() => void props.markRead(item.notificationId)}>{label(item)}</Button>)}<h3>Earlier</h3>{props.notifications.filter(item => item.readAt).map(item => <p className="muted" key={item.notificationId}>{label(item)}</p>)}</aside>;
}

type HubAdapterView = {product:string;connected:boolean;version:number;capabilities:string[]};
type MetricView = {metricId:string;name:string;description:string;unit:string;certified:boolean;adapterVersion:number};
function HubPage(){
 const [adapters,setAdapters]=useState<HubAdapterView[]>([]);const [metrics,setMetrics]=useState<MetricView[]>([]);const [results,setResults]=useState<Array<{runId:string;answer:{metric:string;bySource:Array<{value:number}>;evidence:Array<{content_hash:string;locator:string}>}}>>([]);const [error,setError]=useState('');
 async function refresh(){const [a,m]=await Promise.all([api<{adapters:HubAdapterView[]}>('/api/hub/adapters'),api<{metrics:MetricView[]}>('/api/semantics/metrics')]);setAdapters(a.adapters);setMetrics(m.metrics);}
 useEffect(()=>{void refresh().catch(reason=>setError(reason instanceof Error?reason.message:'Hub data could not be loaded.'));},[]);
 async function setConnection(adapter:HubAdapterView){try{await api(`/api/hub/adapters/${adapter.product}/${adapter.connected?'disconnect':'connect'}`,{method:'POST'});await refresh();}catch(reason){setError(reason instanceof Error?reason.message:'Adapter state could not be changed.');}}
 async function query(metricId:string){try{const result=await api<{runId:string;answer:MetricView & {metric:string;bySource:Array<{value:number}>;evidence:Array<{content_hash:string;locator:string}>}}>('/api/semantics/metrics/'+metricId+'/query',{method:'POST',headers:{'content-type':'application/json'},body:'{}'});setResults(value=>[result,...value]);}catch(reason){setError(reason instanceof Error?reason.message:'Certified metric query failed.');}}
 return <section className="hub-page"><div className="page-heading"><div><h1>Hub integrations</h1><p>Connect trusted analytics services, explore certified measures, and review approved handoffs.</p></div></div>{error&&<p role="alert" className="error">{error}</p>}<article><h2>Integrations</h2>{adapters.length===0?<EmptyState title="No integrations connected" description="This workspace has no connected Hub integrations."/>:adapters.map(item=><div className="hub-adapter" key={item.product}><p>{adapterDisplayName(item.product)} · {item.connected?'Connected':'Not connected'}</p><Button onClick={()=>void setConnection(item)}>{item.connected?`Disconnect ${adapterDisplayName(item.product)}`:`Connect ${adapterDisplayName(item.product)}`}</Button></div>)}</article><article><h2>Certified measures</h2>{metrics.length===0?<EmptyState title="No measures available" description="Certified measures will appear here after a Hub integration is configured."/>:metrics.map(metric=><div className="hub-metric" key={metric.metricId}><h3>{uiCopy(metric.name)}</h3><p>{uiCopy(metric.description)} · {uiCopy(metric.unit)}</p><Button onClick={()=>void query(metric.metricId)}>View {uiCopy(metric.name)}</Button></div>)}{results.map(result=><div key={result.runId} className="assertion-row"><p>{uiCopy(result.answer.metric)}: {result.answer.bySource[0]?.value}</p><p>Evidence: connected Hub result</p></div>)}</article><article><h2>Approved handoffs</h2><EmptyState title="No handoffs available" description="Handoffs will appear after a supported destination and a real report definition are connected."/></article></section>;
}
function FlowSpecPage(props:{id:string}){
 const [versions,setVersions]=useState<Array<{version:number;payload:{name:string;nodes:Array<{id:string;kind:string;capability:string}>};subjectHash:string;sourceSnapshotIds:string[];policyVersion:string;approvalStatus:string;approvedBy:string|null;expiresAt:string;handoffId:string|null;handoffStatus:string|null;receiverRef:string|null}>>([]);const [message,setMessage]=useState('');const [error,setError]=useState('');
 async function refresh(){const data=await api<{versions:typeof versions}>(`/api/flowspecs/${props.id}`);setVersions(data.versions);}
 useEffect(()=>{void refresh().catch(reason=>setError(reason instanceof Error?reason.message:'FlowSpec could not be loaded.'));},[props.id]);
 async function approve(version:number){try{await api(`/api/flowspecs/${props.id}/approve`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({version})});setMessage(`Version ${version} approved.`);await refresh();}catch(reason){setError(reason instanceof Error?reason.message:'A different tenant member must approve this version.');}}
 async function handoff(version:number){try{const result=await api<{status:string;accepted:boolean}>(`/api/flowspecs/${props.id}/handoff`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({version})});setMessage(result.accepted?`Receiver confirmed version ${version}.`:`Receiver status is ${result.status}.`);await refresh();}catch(reason){setError(reason instanceof Error?reason.message:'Handoff could not be confirmed.');}}
 async function reconcile(item:typeof versions[number]){if(!item.handoffId)return;try{const result=await api<{status:string;accepted:boolean}>(`/api/flowspecs/${props.id}/handoff/${item.handoffId}`);setMessage(result.accepted?`Receiver confirmed version ${item.version}.`:`Receiver status is ${result.status}.`);await refresh();}catch(reason){setError(reason instanceof Error?reason.message:'Receiver status could not be checked.');}}
 return <section className="flowspec-page"><div className="page-heading"><div><h1>Approval handoff</h1><p>Each version is approved by a different person. Acceptance appears only after the receiving service confirms it.</p></div></div>{error&&<p role="alert" className="error">{error}</p>}{message&&<p role="status">{message}</p>}{versions.length===0?<EmptyState title="No handoffs yet" description="A handoff will appear here when a real report definition is submitted for review."/>:versions.map(item=><article key={item.version}><h2>{uiCopy(item.payload.name)} · version {item.version}</h2><p>Approval record is securely verified and linked to the source snapshot.</p><p>Policy version {item.policyVersion}</p><ul>{item.payload.nodes.map((node,index)=><li key={index}>{uiCopy(node.kind.replaceAll('_',' '))} · {uiCopy(node.capability.split('.').at(-1)??'approved action')}</li>)}</ul><p>{item.approvalStatus==='approved'?'Approved by another person':'Awaiting approval'} · expires {new Date(item.expiresAt).toLocaleString()}</p>{item.handoffStatus&&<p>Destination status: {uiCopy(item.handoffStatus)}{item.handoffStatus==='confirmed'||item.handoffStatus==='reconciled'?' · Accepted by receiver':''}</p>}{item.approvalStatus==='pending'&&<Button onClick={()=>void approve(item.version)}>Approve version {item.version}</Button>}{item.approvalStatus==='approved'&&!item.handoffStatus&&<Button onClick={()=>void handoff(item.version)}>Send version {item.version} to destination</Button>}{item.handoffId&&(item.handoffStatus==='pending'||item.handoffStatus==='unknown')&&<><Button onClick={()=>void reconcile(item)}>Check delivery status</Button>{item.handoffStatus==='unknown'&&<Button onClick={()=>void handoff(item.version)}>Retry delivery</Button>}</>}</article>)}</section>;
}

function App() {
  const [path, setPath] = useState(location.pathname + location.search);
  const [usage, setUsage] = useState<Usage | null>(null);
  const [connections, setConnections] = useState<Connection[]>([]);
  const [user,setUser]=useState<{email:string;displayName:string}|null>(null);
  const [unauthorized, setUnauthorized] = useState(false);
  const [groups, setGroups] = useState<NavGroups>(loadGroups);
  const [profileOpen, setProfileOpen] = useState(false);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [notificationsOpen, setNotificationsOpen] = useState(false);
  const [recentQuestions, setRecentQuestions] = useState<Array<{planId:string;question:string}>>([]);
  const [chatInstance, setChatInstance] = useState(0);
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [error, setError] = useState('');
  async function reloadConnections() { const result = await api<{ connections: Connection[] }>('/api/connections'); setConnections(result.connections); }
  async function reloadNotifications() { const result = await api<{ notifications: Notification[] }>('/api/notifications'); setNotifications(result.notifications); }
  useEffect(() => {
    void Promise.all([api<Usage>('/api/usage').then(setUsage),api<{user:{email:string;displayName:string}}>('/api/auth/me').then(result=>setUser(result.user)),reloadConnections(),reloadNotifications()]).catch(reason => {
      if (reason instanceof Error && reason.message === 'unauthorized') setUnauthorized(true);
      else setError('Workspace data could not be loaded.');
    });
  }, []);
  useEffect(() => { void api<{questions:Array<{planId:string;question:string}>}>('/api/me/saved-questions').then(result=>setRecentQuestions(result.questions)).catch(()=>undefined); }, []);
  useEffect(() => { try { localStorage.setItem('nav-workspace', String(groups.workspace)); localStorage.setItem('nav-platform', String(groups.platform)); localStorage.setItem('nav-recent', String(groups.recent)); } catch { /* Navigation still works when storage is disabled. */ } }, [groups]);
  useEffect(() => { const pop = () => setPath(location.pathname + location.search); addEventListener('popstate', pop); return () => removeEventListener('popstate', pop); }, []);
  if (path === '/invite' || path.startsWith('/invite?')) return <InviteAcceptPage />;
  if (path.startsWith('/login') || unauthorized) return <Login />;
  const navigate = (url: string) => { history.pushState({}, '', url); setPath(url); setError(''); };
  const toggle = (group: keyof NavGroups) => setGroups(value => ({ ...value, [group]: !value[group] }));
  const newChat = () => { setChatInstance(value=>value+1); navigate('/'); };
  async function signOut() { await fetch('/api/auth/logout', { method: 'POST' }); const tenant=localStorage.getItem('si-login-tenant'); location.assign(tenant?`/login?tenant=${encodeURIComponent(tenant)}`:'/login'); }
  async function markRead(id: string) { await api(`/api/notifications/${id}/read`, { method: 'POST' }); await reloadNotifications(); }
  async function startRecent(planId:string) { try { const result=await api<{runId:string}>(`/api/me/saved-questions/${planId}/start`,{method:'POST'}); navigate(`/runs/${result.runId}`); } catch { navigate('/my-agent'); } }
  const currentConnection = new URLSearchParams(path.split('?')[1] ?? '').get('connection') ?? path.split('/')[2];
  const usageTypes=Object.entries(usage?.active_connectors.by_type??{});
  const totalActiveConnectors=usageTypes.reduce((total,[,count])=>total+count,0);
  const toolConnectorCount=usageTypes.filter(([type])=>type.includes('tableau')||type.includes('power_bi')).reduce((total,[,count])=>total+count,0);
  const sourceConnectorCount=totalActiveConnectors-toolConnectorCount;
  let page: React.ReactNode;
  if (path.startsWith('/invites')) page = <InvitesPage />;
  else if (path.startsWith('/usage')) page = <section className="usage-page"><div className="page-heading"><div><h1>Usage</h1><p>Pricing is per user and per connected source.</p></div><Badge tone="muted">Current billing period</Badge></div><div className="usage-summary"><article><strong>{usage?.active_users??0}</strong><span>Active users</span></article><article><strong>{totalActiveConnectors}</strong><span>Active connectors</span></article><article><strong>{sourceConnectorCount} + {toolConnectorCount}</strong><span>Data sources + tool connectors</span></article></div><Table caption="Active connector counts by type" headers={['Connection type','Connectors','Category']} rows={usageTypes.map(([type,count])=>[connectorTypeLabel(type),count,type.includes('tableau')||type.includes('power_bi')?'Tool connector':'Data source'])}/><article className="usage-model"><h2>Model usage</h2><div className="usage-summary"><div><strong>{((usage?.model_usage.input_tokens??0)+(usage?.model_usage.output_tokens??0)).toLocaleString()}</strong><span>Tokens this period</span></div><div><strong>USD {(usage?.model_usage.cost_usd??0).toFixed(4)}</strong><span>Cost this period</span></div><div><strong>USD {(usage?.model_usage.daily_cost_cap_usd??2).toFixed(2)}</strong><span>Daily model cap · {usage?.model_usage.daily_token_cap.toLocaleString()??'100,000'} tokens</span></div></div></article></section>;
  else if (path.startsWith('/connectors')) page = <ConnectorsPage connections={connections} reload={reloadConnections} navigate={navigate} />;
  else if (path.startsWith('/profile/')) page = <ProfilePage connectionId={currentConnection ?? ''} navigate={navigate} />;
  else if (path.startsWith('/dictionary')) page = currentConnection ? <DictionaryPage connectionId={currentConnection} /> : <section><div className="page-heading"><div><h1>Dictionary</h1><p>Browse harvested tables, fields, and their descriptions.</p></div></div>{connections.filter(connection=>connection.status==='active').length?<div className="cards">{connections.filter(connection=>connection.status==='active').map(connection=><article key={connection.connectionId}><h2>{connectionDisplayName(connection)}</h2><p>{connectorTypeLabel(connection.connectorType)}</p><Button onClick={()=>navigate(`/dictionary?connection=${connection.connectionId}`)}>Open Dictionary</Button></article>)}</div>:<EmptyState title="No dictionaries yet" description="Add a connector to harvest its tables and columns." action={<Button variant="primary" onClick={()=>navigate('/connectors')}>Add a connector</Button>}/>}</section>;
  else if (path.startsWith('/controls')) page = <ControlsPage {...(currentConnection?{connectionId:currentConnection}:{})} connections={connections} navigate={navigate}  />;
  else if (path.startsWith('/er') || path.startsWith('/lineage') || path.startsWith('/bi-reports')) page = <LineageWorkspace path={path} navigate={navigate} />;
  else if (path.startsWith('/approval-matrix')) page = <ApprovalMatrix />;
  else if (path.startsWith('/reports')) page = <ReportsPage />;
  else if (path.startsWith('/hub')) page = <HubPage />;
  else if (path.startsWith('/flowspecs/')) page = <FlowSpecPage id={path.split('/')[2]??''} />;
  else if (path.startsWith('/my-agent')) page = <MyAgentPage />;
  else if (path.startsWith('/agents')) page = <AgentsPage connections={connections} />;
  else if(path.startsWith('/runs/'))page=<AnalyticWorkspace key={chatInstance} connections={connections} navigate={navigate} notifications={notifications} recentQuestions={recentQuestions} markRead={markRead} userName={user?.displayName??''} runId={path.split('/')[2]}/>;
  else page = <AnalyticWorkspace key={chatInstance} connections={connections} navigate={navigate} notifications={notifications} recentQuestions={recentQuestions} markRead={markRead} userName={user?.displayName??''}/>;

  const unreadCount=notifications.filter(item=>!item.readAt).length;
  return <div className={`app${sidebarCollapsed?' app--collapsed':''}`}><aside className="sidebar">
    <div className="brand"><Logo /><b>Scale Insyght</b><Button className="collapse-sidebar" variant="ghost" aria-label={sidebarCollapsed?'Expand sidebar':'Collapse sidebar'} onClick={()=>setSidebarCollapsed(value=>!value)}>◧</Button></div>
    <Button className="new-chat" variant="secondary" onClick={newChat}><span aria-hidden="true">＋</span> New chat</Button>
    <Button className="nav-notifications" variant="ghost" aria-expanded={notificationsOpen} onClick={() => { setNotificationsOpen(value => !value); if (!notificationsOpen) void reloadNotifications(); }}><span aria-hidden="true">♧</span><span>Notifications</span>{unreadCount>0&&<span className="nav-count">{unreadCount}</span>}</Button>
    <nav aria-label="Main navigation">
      <Button className="section-toggle" aria-expanded={groups.workspace} onClick={() => toggle('workspace')}>Workspace <span aria-hidden="true">{groups.workspace ? '⌄' : '›'}</span></Button>
      {groups.workspace && <div className="nav-items"><a href="/" aria-current={path === '/' ? 'page' : undefined} onClick={event => { event.preventDefault(); navigate('/'); }}><span aria-hidden="true">⌂</span><span>Home</span>{recentQuestions.length>0&&<span className="nav-count">{recentQuestions.length}</span>}</a><a href="/connectors" aria-current={path.startsWith('/connectors') ? 'page' : undefined} onClick={event => { event.preventDefault(); navigate('/connectors'); }}><span aria-hidden="true">♧</span><span>Connectors</span></a><a href="/dictionary" aria-current={path.startsWith('/dictionary') ? 'page' : undefined} onClick={event => { event.preventDefault(); navigate('/dictionary'); }}><span aria-hidden="true">▤</span><span>Dictionary</span></a><a href="/lineage" aria-current={path.startsWith('/lineage') || path.startsWith('/er') ? 'page' : undefined} onClick={event => { event.preventDefault(); navigate('/lineage'); }}><span aria-hidden="true">⌘</span><span>Lineage</span></a></div>}
      <Button className="section-toggle" aria-expanded={groups.platform} onClick={() => toggle('platform')}>Platform <span aria-hidden="true">{groups.platform ? '⌄' : '›'}</span></Button>
      {groups.platform && <div className="nav-items"><a href="/agents" onClick={event=>{event.preventDefault();navigate('/agents');}}><span aria-hidden="true">♙</span><span>Agents</span></a><a href="/bi-reports" onClick={event=>{event.preventDefault();navigate('/bi-reports');}}><span aria-hidden="true">▧</span><span>BI reports</span></a><a href="/hub" onClick={event=>{event.preventDefault();navigate('/hub');}}><span aria-hidden="true">◈</span><span>Hub integrations</span></a><a href="/approval-matrix" onClick={event => { event.preventDefault(); navigate('/approval-matrix'); }}><span aria-hidden="true">✓</span><span>Approval matrix</span></a><a href="/controls" onClick={event => { event.preventDefault(); navigate('/controls'); }}><span aria-hidden="true">⚙</span><span>Controls</span></a></div>}
    </nav>
    <div className="recent"><Button className="section-toggle" aria-expanded={groups.recent} onClick={() => toggle('recent')}>Recent conversations <span aria-hidden="true">{groups.recent ? '⌄' : '›'}</span></Button>{groups.recent&&<div className="recent-list">{recentQuestions.length?recentQuestions.slice(0,5).map(item=><Button key={item.planId} variant="ghost" onClick={()=>void startRecent(item.planId)}><span aria-hidden="true">◌</span>{item.question}</Button>):<p>No conversations yet. Start a question and saved answers will appear here.</p>}</div>}</div>
    <div className="profile"><Button variant="ghost" aria-haspopup="menu" aria-expanded={profileOpen} onClick={() => setProfileOpen(value => !value)}><span className="avatar">{initials(user?.displayName)}</span><span className="profile-name"><b>{user?.displayName||'Account'}</b></span><span aria-hidden="true">⌃</span></Button>{profileOpen && <div role="menu"><Button variant="ghost" role="menuitem" onClick={() => navigate('/my-agent')}>My agent</Button><Button variant="ghost" role="menuitem" onClick={() => navigate('/invites')}>Invite members</Button><Button variant="ghost" role="menuitem" onClick={() => navigate('/reports')}>Reports</Button><Button variant="ghost" role="menuitem" onClick={() => navigate('/hub')}>Hub integrations</Button><Button variant="ghost" role="menuitem" onClick={() => navigate('/usage')}>Usage</Button><Button variant="ghost" role="menuitem" onClick={signOut}>Sign out</Button></div>}</div>
  </aside><main className="main"><header className="topbar"><span>Scale Insyght</span></header><div className="view" id="main-content">{error && <p className="error" role="alert">{error}</p>}{page}</div>{notificationsOpen && <NotificationPanel notifications={notifications} close={() => setNotificationsOpen(false)} markRead={markRead} />}</main></div>;
}

createRoot(document.getElementById('root')!).render(<App />);
